package com.sanctuarygames.createtransit;
import com.sanctuarygames.createtransit.elevator.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.*;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder("createtransit") @PrefixGameTestTemplate(false)
public final class ElevatorSolidGameTests {
 static void check(boolean ok,String m){if(!ok)throw new GameTestAssertException(m);}
 @GameTest(template="empty",timeoutTicks=40)
 public static void solid_columns_have_only_floor_and_roof_trims_and_update_on_removal(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(3,2,3));for(var facing:Direction.Plane.HORIZONTAL){var q=p.relative(facing,3);for(var b:new net.minecraft.world.level.block.Block[]{ElevatorRegistry.SOLID_WALL.get(),ElevatorRegistry.SOLID_CORNER.get()}){for(int row=0;row<3;row++)l.setBlock(q.above(row),b.defaultBlockState().setValue(ElevatorPartBlock.FACING,facing),3);for(int row=0;row<3;row++){var s=l.getBlockState(q.above(row));check(s.getValue(ElevatorSolidBlock.DOWN)==(row>0)&&s.getValue(ElevatorSolidBlock.UP)==(row<2),"Only column ends show lamps in every facing");}l.destroyBlock(q.above(),false);check(!l.getBlockState(q).getValue(ElevatorSolidBlock.UP)&&!l.getBlockState(q.above(2)).getValue(ElevatorSolidBlock.DOWN),"Breaking column restores exposed edges");l.destroyBlock(q,false);l.destroyBlock(q.above(2),false);}}var wall=ElevatorRegistry.SOLID_WALL.get().defaultBlockState();l.setBlock(p,wall,3);l.setBlock(p.above(),ElevatorRegistry.CONTROL_PANEL.get().defaultBlockState(),3);l.setBlock(p.above(2),wall,3);check(l.getBlockState(p.above()).getValue(ElevatorSolidBlock.UP)&&l.getBlockState(p.above()).getValue(ElevatorSolidBlock.DOWN),"Control panel joins metal wall column");var door=ElevatorRegistry.SOLID_DOOR.get().defaultBlockState().setValue(ElevatorDoorBlock.ROW,1);l.setBlock(p.east(2),door,2|16);l.setBlock(p.east(2).above(),ElevatorRegistry.DOOR_HEADER.get().defaultBlockState(),3);check(l.getBlockState(p.east(2).above()).getValue(ElevatorSolidBlock.DOWN),"Door header has roof trim without false floor trim");h.succeed();}
 @GameTest(template="elevator_shaft",batch="elevators",timeoutTicks=800)
 public static void solid_quickbuild_connected_wall_states_and_dyes_survive_travel(GameTestHelper h){var d=ElevatorGameTests.fixture(h,false,true);var l=h.getLevel();var origin=d.anchor();var expected=new java.util.HashMap<BlockPos,net.minecraft.world.level.block.state.BlockState>();for(int x=-3;x<=3;x++)for(int y=1;y<=3;y++)for(int z=-3;z<=3;z++){var q=origin.offset(x,y,z);var s=l.getBlockState(q);if(s.getBlock() instanceof ElevatorSolidBlock){expected.put(q,s);var above=l.getBlockState(q.above());var below=l.getBlockState(q.below());boolean up=above.getBlock() instanceof ElevatorSolidBlock&&above.getValue(ElevatorPartBlock.FACING)==s.getValue(ElevatorPartBlock.FACING);boolean down=below.getBlock() instanceof ElevatorSolidBlock&&below.getValue(ElevatorPartBlock.FACING)==s.getValue(ElevatorPartBlock.FACING)||below.getBlock() instanceof ElevatorDoorBlock&&below.getValue(ElevatorPartBlock.FACING)==s.getValue(ElevatorPartBlock.FACING);check(s.getValue(ElevatorSolidBlock.UP)==up&&s.getValue(ElevatorSolidBlock.DOWN)==down,"NBT QuickBuild resolves connected wall properties");((ElevatorPartEntity)l.getBlockEntity(q)).setColors(14,3);}}check(!expected.isEmpty(),"Solid QuickBuild includes wall modules");check(d.assemble(),"Connected wall cabin assembles");d.requestFloor(origin.getY()+12);h.onEachTick(()->{if(d.phase()==ElevatorDriveEntity.IDLE&&Math.abs(d.offset()-12)<.001){ElevatorGameTests.restored(d);for(var entry:expected.entrySet()){var q=entry.getKey().above(12);check(l.getBlockState(q).equals(entry.getValue()),"Restored wall preserves connected trim state: "+q+" expected "+entry.getValue()+" actual "+l.getBlockState(q));var be=(ElevatorPartEntity)l.getBlockEntity(q);check(be.paint()==14&&be.accent()==3,"Wall and trim dyes survive motion");}h.succeed();}});}
}
